// Phase 2F (2026-05-28) — let the PWA write back to the reconcile state
// file so user-marked-as-noise rows stop surfacing in the 'Needs attention'
// view. Workflow 18 reads the same state file, so a 5-min refresh in the
// PWA picks up the change.
//
// POST body shape (from PWA): {
//   institution: 'chase8168_activity_20260527.qfx',
//   fitid: '202605260'
// }
//
// Action: read whichever reconcile state file exists, add or update the
// reconciled_ids[<institution>:<fitid>] entry with status='noise-skip', and
// write back to the same path. Two state-file paths supported because the
// path was migrated mid-build; this workflow heals either.

const fs = require('fs');

const STATE_FILES = [
  '/data/chatin/_reconcile_state.json',
  '/data/finance-events/_reconcile_state.json'
];

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const institution = (body.institution || '').toString().trim().toLowerCase();
const fitid = (body.fitid || '').toString().trim();
const reason = (body.reason || 'user-marked').toString();

if (!institution || !fitid) {
  return [{ json: { ok: false, error: 'institution and fitid are required' } }];
}

const key = institution + ':' + fitid;

let statePath = null;
let state = { reconciled_ids: {} };
for (const p of STATE_FILES) {
  try {
    state = JSON.parse(fs.readFileSync(p, 'utf8'));
    statePath = p;
    break;
  } catch (_) {}
}
// If neither path existed, default to /data/chatin/ which is the path the
// PWA's path-fix migration moved everything to.
if (!statePath) statePath = STATE_FILES[0];
if (!state.reconciled_ids) state.reconciled_ids = {};

const prev = state.reconciled_ids[key];
state.reconciled_ids[key] = {
  status: 'noise-skip',
  at: new Date().toISOString(),
  marked_by: 'pwa-user',
  reason,
  prev_status: prev ? prev.status : null
};

try { fs.writeFileSync(statePath, JSON.stringify(state, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String(e) } }]; }

return [{ json: { ok: true, key, statePath, prev_status: prev ? prev.status : null } }];
